# Print keys at top level
def find_keys(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            print(f'{path}.{k}' if path else k)
            if isinstance(v, (dict, list)):
                find_keys(v, f'{path}.{k}' if path else k)
    elif isinstance(d, list) and len(d) > 0:
        print(f'{path} is a list with {len(d)} items')

find_keys(data)
