import json
with open('/app/resources/treasury_bulletin_1970_05.json', 'r') as f:
    data = json.load(f)

# Search for 'unmatured' in the data
def search_unmatured(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            if 'unmatured' in str(k).lower():
                print(f'Found key: {path}.{k}')
                print(f'Value: {v}')
            if isinstance(v, (dict, list)):
                search_unmatured(v, f'{path}.{k}' if path else k)
    elif isinstance(d, list) and len(d) > 0:
        for i, item in enumerate(d):
            if isinstance(item, (dict, list)):
                search_unmatured(item, f'{path}[{i}]')

search_unmatured(data)
