python3 -c "
import json
with open('/app/resources/treasury_bulletin_1970_05.json', 'r') as f:
    data = json.load(f)

# Search for 'redemption' in the data
def search_redemption(d, path='', depth=0):
    if depth > 4:
        return
    if isinstance(d, dict):
        for k, v in d.items():
            if 'redemption' in str(k).lower() or 'unmature' in str(k).lower():
                print(f'Found key: {path}.{k}' if path else k)
                print(f'Value: {v}')
            if isinstance(v, (dict, list)):
                search_redemption(v, f'{path}.{k}' if path else k, depth+1)
    elif isinstance(d, list) and len(d) > 0 and depth < 3:
        for i, item in enumerate(d[:5]):  # Only first 5 to avoid too much output
            if isinstance(item, (dict, list)):
                search_redemption(item, f'{path}[{i}]', depth+1)

search_redemption(data)
" 2>&1

